struct Point { let time: Date; let value: Double }
struct ActionRecord: Codable, Identifiable { var id=UUID(); var date=Date(); var message:String; var baselineCPU:Double?; var resultCPU:Double?; var resultDate:Date?; var session:UUID? = nil }
struct Proc: Identifiable { let id: Int32; let user: String; let cpu: Double; let mem: Double; let rss: Int; let start: String; let command: String
 var name: String { URL(fileURLWithPath: command.components(separatedBy:" ").first ?? command).lastPathComponent }
 var system: Bool { command.hasPrefix("/System/") || command.hasPrefix("/usr/") || command.hasPrefix("/sbin/") || command.hasPrefix("/bin/") }
 var bundlePath:String? { guard let r=command.range(of:".app/") else{return nil}; return String(command[..<r.upperBound].dropLast()) }
