 func updatePreferences(){ UserDefaults.standard.set(trackProcessHistory,forKey:"trackProcessHistory"); UserDefaults.standard.set(profile.rawValue,forKey:"collectionProfile"); UserDefaults.standard.set(macmonEnabled,forKey:"macmonEnabled"); if !paused && !busy { scheduleNext() }; UserDefaults.standard.set(cpuThreshold,forKey:"cpuThreshold"); if !macmonEnabled { latestMacMetrics=nil; macmonMessage="Collecteur désactivé" }; UserDefaults.standard.set(retentionHours,forKey:"retentionHours"); UserDefaults.standard.set(alertsEnabled,forKey:"alertsEnabled"); samples=samples.filter{$0.time > Date().addingTimeInterval(-Double(retentionHours)*3600)}; saveHistory(); do {try historyDB?.prune(before:Date().addingTimeInterval(-Double(retentionHours)*3600));lastPrune=Date()} catch {persistenceWarning="Purge historique impossible : \(error.localizedDescription)"} }
