 func exportReport(){ let panel=NSSavePanel();panel.allowedContentTypes=[.plainText];panel.nameFieldStringValue="MacPilot-rapport.txt";guard panel.runModal() == .OK,let url=panel.url else{return};let now=Date();let last=model.samples.last;let report="MacPilot — rapport local\nDate : \(now.formatted(date:.abbreviated,time:.shortened))\nMatériel : \(model.hardware)\nCPU : \(model.cpu)\nMémoire : \(model.memory)\nPression : \(model.pressure)\nGPU : \(model.gpu)\nBatterie : \(batteryText)\nStockage : \(model.disk)\nDernier relevé : \(last?.time.formatted(date:.abbreviated,time:.shortened) ?? "indisponible")\nRelevés : \(model.samples.count)\n\nInstantanés indicatifs ; noms et commandes des processus exclus.\n";do{try report.write(to:url,atomically:true,encoding:.utf8);result="Rapport enregistré."}catch{result="Impossible d’enregistrer : \(error.localizedDescription)"} }
 func bytes(_ kb:Int)->String { ByteCountFormatter.string(fromByteCount:Int64(kb)*1024,countStyle:.memory) }
 func openMole(_ command:String){ let allowed=["status","analyze","clean","optimize","purge","installer","uninstall","clean --whitelist","optimize --whitelist","purge --paths","clean --dry-run","optimize --dry-run","purge --dry-run","installer --dry-run","uninstall --dry-run"]; guard allowed.contains(command) else{return}; let script="tell application \"Terminal\"\nactivate\ndo script \"/opt/homebrew/bin/mo \(command)\"\nend tell"; var e:NSDictionary?; NSAppleScript(source:script)?.executeAndReturnError(&e); if e != nil { result="Impossible d’ouvrir Terminal. Autorisez MacPilot à contrôler Terminal dans Réglages Système → Confidentialité et sécurité → Automatisation." } }
}
struct ControlPanel:View {
 @Environment(\.dismiss) private var dismiss
 @State private var volume=50.0
 @State private var volumeLoaded=false
 @State private var busy=false
 @State private var message=""
 @State private var confirmSleep=false
 @State private var confirmLock=false
 var body:some View { VStack(alignment:.leading,spacing:18) {
 HStack { Label("Piloter le Mac",systemImage:"slider.horizontal.3").font(.title2.bold()); Spacer(); Button("Fermer"){dismiss()} }
 GroupBox("Son") { VStack(alignment:.leading,spacing:10) { HStack { Image(systemName:"speaker.wave.2"); Slider(value:$volume,in:0...100,step:1).disabled(!volumeLoaded || busy); Text("\(Int(volume)) %").monospacedDigit().frame(width:55); Button("Appliquer"){applyVolume()}.disabled(!volumeLoaded || busy) }; HStack { Button("Actualiser le volume"){loadVolume()}.disabled(busy); Button("Couper le son"){setMute(true)}.disabled(busy); Button("Rétablir le son"){setMute(false)}.disabled(busy) }; Text("Le volume est appliqué à la sortie audio actuelle.").font(.caption).foregroundStyle(.secondary) }.padding(8) }
 GroupBox("Session") { HStack { Button("Verrouiller l’écran"){confirmLock=true}; Button("Mettre en veille"){confirmSleep=true}; Spacer() }.padding(8) }
 GroupBox("Ouvrir les réglages") { VStack(alignment:.leading,spacing:10) { HStack { shortcut("Wi-Fi","x-apple.systempreferences:com.apple.wifi-settings-extension"); shortcut("Bluetooth","x-apple.systempreferences:com.apple.BluetoothSettings"); shortcut("Batterie","x-apple.systempreferences:com.apple.Battery-Settings.extension"); shortcut("Son","x-apple.systempreferences:com.apple.Sound-Settings.extension") }; HStack { shortcut("Écrans","x-apple.systempreferences:com.apple.Displays-Settings.extension"); shortcut("Connexion","x-apple.systempreferences:com.apple.LoginItems-Settings.extension"); shortcut("Stockage","x-apple.systempreferences:com.apple.settings.Storage") } }.padding(8) }
 GroupBox("Applications") { HStack { Button("Ouvrir une application…"){chooseApplication()}; Button("Moniteur d’activité"){openApp(URL(fileURLWithPath:"/System/Applications/Utilities/Activity Monitor.app"))}; Spacer() }.padding(8) }
 if !message.isEmpty { Text(message).font(.callout).foregroundStyle(.secondary).textSelection(.enabled) }; Spacer()
 }.padding(24).frame(minWidth:690,minHeight:560).onAppear{loadVolume()}
 .alert("Mettre le Mac en veille ?",isPresented:$confirmSleep){Button("Mettre en veille"){execute("/usr/bin/pmset",["sleepnow"],success:"Demande de mise en veille envoyée.")};Button("Annuler",role:.cancel){} } message:{Text("La connexion et les tâches en cours peuvent être interrompues.")}
 .alert("Verrouiller l’écran ?",isPresented:$confirmLock){Button("Verrouiller"){execute("/usr/bin/osascript",["-e","tell application \"System Events\" to keystroke \"q\" using {control down, command down}"],success:"Raccourci de verrouillage envoyé.")};Button("Annuler",role:.cancel){} } message:{Text("macOS peut demander l’autorisation d’automatisation et d’accessibilité pour envoyer le raccourci système.")}
 }
 func execute(_ path:String,_ args:[String],success:String){ guard !busy else{return}; busy=true; message="Exécution…"; DispatchQueue.global(qos:.utility).async { let r=boundedCommand(path,args,timeout:8,maximumBytes:8192); DispatchQueue.main.async {busy=false; message=r.succeeded ? success : "Action non confirmée : \(r.timedOut ? "délai dépassé" : (r.output.isEmpty ? "code \(r.exitCode.map(String.init) ?? "indisponible")" : r.output))"} } }
 func loadVolume(){ guard !busy else{return}; busy=true; DispatchQueue.global(qos:.utility).async { let r=boundedCommand("/usr/bin/osascript",["-e","get volume settings"],timeout:8,maximumBytes:8192); let range=r.output.range(of:"output volume:[0-9]+",options:.regularExpression); let v=range.flatMap{Int(r.output[$0].split(separator:":").last ?? "")}; DispatchQueue.main.async {busy=false; if r.succeeded, let v=v,(0...100).contains(v) {volume=Double(v);volumeLoaded=true} else {volumeLoaded=false;message="Lecture du volume indisponible : \(r.output)"} } } }
 func applyVolume(){ guard let script=volumeCommand(Int(volume)) else {message="Volume invalide.";return}; execute("/usr/bin/osascript",["-e",script],success:"Volume appliqué.") }
 func setMute(_ muted:Bool){execute("/usr/bin/osascript",["-e","set volume output muted \(muted ? "true" : "false")"],success:muted ? "Son coupé." : "Son rétabli.")}
 func shortcut(_ title:String,_ address:String)->some View { Button(title){ if let url=URL(string:address), NSWorkspace.shared.open(url) {message="Réglages ouverts : \(title)."} else {message="Impossible d’ouvrir les réglages \(title)."} } }
 func openApp(_ url:URL){ NSWorkspace.shared.openApplication(at:url,configuration:NSWorkspace.OpenConfiguration()){ _,error in DispatchQueue.main.async {message=error.map{"Ouverture impossible : \($0.localizedDescription)"} ?? "Application ouverte."} } }
 func chooseApplication(){let p=NSOpenPanel();p.canChooseFiles=true;p.canChooseDirectories=false;p.allowedContentTypes=[.applicationBundle];p.prompt="Ouvrir";if p.runModal() == .OK,let u=p.url {openApp(u)}}
}
struct MemoryPanel:View {
 @ObservedObject var model:Monitor
 @Environment(\.dismiss) var dismiss
 @State private var selected:Proc?
 @State private var message=""
 func members(_ p:Proc)->[Proc] { guard let path=p.bundlePath else {return [p]}; return model.processes.filter{$0.user == p.user && $0.bundlePath == path && !$0.system} }
 var candidates:[Proc] { model.processes.filter { p in p.user == NSUserName() && !p.system && p.id != ProcessInfo.processInfo.processIdentifier && NSRunningApplication(processIdentifier:p.id)?.activationPolicy == .regular }.sorted{$0.rss > $1.rss} }
 var body:some View { VStack(alignment:.leading,spacing:14) {
 HStack { Text("Optimiser la RAM").font(.title2.bold()); Spacer(); Button("Fermer"){dismiss()} }
 Text(model.pressure.isEmpty ? "Pression mémoire indisponible" : model.pressure.replacingOccurrences(of:"System-wide memory free percentage:",with:"Marge mémoire :"))
 Text("Quittez les applications dont vous n’avez plus besoin. macOS réutilise automatiquement sa mémoire de cache. Les valeurs ci-dessous correspondent au processus principal ; dépliez les groupes dans la vue Applications pour voir les sous-processus. La mémoire partagée peut apparaître dans plusieurs processus.").font(.callout).foregroundStyle(.secondary)
 if !message.isEmpty { Text(message).foregroundStyle(.secondary) }
 if let margin=model.samples.last?.memoryFree, margin >= 40 { Text("Marge mémoire actuellement confortable : aucune fermeture n’est nécessaire sur la seule base de ce relevé.").font(.callout).foregroundStyle(.secondary) }
 if candidates.isEmpty { Text("Aucune application utilisateur éligible détectée.").foregroundStyle(.secondary) }
 List(candidates) { p in DisclosureGroup { ForEach(members(p).sorted{$0.rss > $1.rss}) { child in HStack { Text("\(child.name) · PID \(child.id)").lineLimit(1); Spacer(); Text(ByteCountFormatter.string(fromByteCount:Int64(child.rss)*1024,countStyle:.memory)).monospacedDigit() }.font(.caption).foregroundStyle(.secondary) } } label: { HStack { VStack(alignment:.leading) { Text(NSRunningApplication(processIdentifier:p.id)?.localizedName ?? p.group).fontWeight(.medium); Text("\(members(p).count) processus associés · mémoire partagée possible").font(.caption).foregroundStyle(.secondary) }; Spacer(); VStack(alignment:.trailing) { Text(ByteCountFormatter.string(fromByteCount:Int64(p.rss)*1024,countStyle:.memory)).monospacedDigit(); Text("principal").font(.caption2).foregroundStyle(.secondary) }; Button("Quitter"){selected=p} } } }
 }.padding(24).frame(minWidth:700,minHeight:500)
 .alert(item:$selected) { p in Alert(title:Text("Quitter \(p.group) ?"),message:Text("L’application pourra vous demander d’enregistrer votre travail. La mémoire libérée dépend de macOS et peut être différente de la valeur affichée."),primaryButton:.destructive(Text("Quitter")){ if model.isSame(p), let app=NSRunningApplication(processIdentifier:p.id), app.terminate() { model.note("Demande de fermeture : \(p.group)",measure:true); message="Demande envoyée ; vérification dans 8 secondes."; let requested=Date(); let before=model.samples.last?.memoryFree; DispatchQueue.main.asyncAfter(deadline:.now()+8) { let closed=app.isTerminated; let after=model.samples.last.flatMap { $0.time > requested ? $0.memoryFree : nil }; message = closed ? "Application fermée." : "Fermeture non confirmée ; elle peut attendre votre réponse."; if let before=before, let after=after { message += String(format:" Marge mémoire : %.0f %% avant, %.0f %% maintenant. D’autres activités peuvent avoir changé.",before,after) } } } else { message="L’application a changé ou a refusé la demande ; aucune fermeture confirmée." }; model.refresh() },secondaryButton:.cancel()) }
 }
}
