 VStack(alignment:.leading,spacing:12) { HStack { VStack(alignment:.leading){ Text("Résultats Mole").font(.title2.bold()); Text(model.moleLabel).font(.caption).foregroundStyle(.secondary) }; Spacer(); if model.moleBusy { ProgressView().controlSize(.small) }; Button("Fermer",action:close) }
 Text("L’historique s’affiche ici. Les commandes interactives et aperçus Mole s’ouvrent dans Terminal.").font(.caption).foregroundStyle(.secondary)
 TextField("Rechercher dans le résultat",text:$search).textFieldStyle(.roundedBorder)
 ScrollView { Text(output.isEmpty ? "Aucun résultat correspondant." : output).font(.system(.caption,design:.monospaced)).frame(maxWidth:.infinity,alignment:.leading).textSelection(.enabled) }.frame(maxWidth:.infinity,maxHeight:.infinity)
 }.padding(22).frame(minWidth:600,maxWidth:.infinity,maxHeight:.infinity) }.frame(minWidth:950,minHeight:650) }
 func preview(_ title:String,_ command:String)->some View { Button { search=""; model.runMolePreview(command) } label:{ Label(title,systemImage:command == "history" ? "clock.arrow.circlepath" : "doc.text.magnifyingglass").frame(maxWidth:.infinity,alignment:.leading) }.buttonStyle(.plain).disabled(model.moleBusy) }
 func interactive(_ title:String,_ command:String,_ detail:String)->some View { Button { openTerminal(command,detail) } label:{ Label(title,systemImage:"terminal").frame(maxWidth:.infinity,alignment:.leading) }.buttonStyle(.plain) }
}
